{
 "id": "01a0fcec-55a5-7e01-992a-930cfaa34c25",
 "content": "scripts/export.py produces the monthly invoice report that Finance imports into their accounting tool at the start of each month. It runs from the ops cron on the 2nd at 06:00 UTC and writes one file per environment to EXPORT_BUCKET under `exports/<YYYY-MM>/invoices.csv`. Finance reconciles the totals against the ledger, so every finalized invoice of the month must appear exactly once, including zero-amount ones; drafts are excluded. Columns, in order: invoice id, customer id, subtotal, tax, total, finalized date. Amounts are integer cents with no currency symbol. Format (Finance moved to a new accounting tool in late September 2026, replacing the German-locale tool that needed `;` and DD.MM.YYYY): plain comma-separated, dates ISO `YYYY-MM-DD` (strftime `%Y-%m-%d`). UTF-8 without a BOM.",
 "premise": "while Finance uses the accounting tool adopted in late September 2026",
 "invalidated_by": [
  "scripts/export.py"
 ]
}
